#pragma once

namespace viewer
{
    inline constexpr char INDEX_HTML[] = R"HTML(<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>LevelDB Viewer</title>
<style>
:root{font-family:Inter,Segoe UI,Arial,sans-serif;color:#172033;background:#f5f7fb;line-height:1.45}*{box-sizing:border-box}body{margin:0}button,input,select,textarea{font:inherit}button{cursor:pointer}header{height:66px;background:#fff;border-bottom:1px solid #e5e9f2;display:flex;align-items:center;justify-content:space-between;padding:0 28px;position:sticky;top:0;z-index:5}.brand{display:flex;align-items:center;gap:11px}.brand-mark{width:32px;height:32px;border-radius:10px;background:#2563eb;color:#fff;display:grid;place-items:center;font-weight:800}.brand h1{font-size:19px;margin:0}.connection{font-size:13px;color:#087443}.top-query{display:flex;align-items:center;gap:8px;margin-left:auto;margin-right:20px}.top-query .input{width:min(360px,30vw);padding:8px 10px}.top-query .primary{padding:8px 12px}.connection i{display:inline-block;width:8px;height:8px;background:#16a36a;border-radius:50%;margin-right:6px}.layout{display:flex;min-height:calc(100vh - 66px)}nav{width:190px;background:#fff;border-right:1px solid #e5e9f2;padding:18px 12px;flex:none}nav button{display:flex;align-items:center;gap:10px;width:100%;border:0;background:transparent;color:#667085;text-align:left;padding:11px 13px;border-radius:9px;margin-bottom:4px}nav button:hover,nav button.active{background:#edf4ff;color:#175cd3}.nav-icon{width:18px;text-align:center;color:inherit}.main{width:min(1480px,100%);margin:0 auto;padding:28px}.page h2{font-size:24px;margin:0 0 5px}.page h3{font-size:16px;margin:0}.muted{color:#667085;font-size:13px}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:22px 0}.card,.panel{background:#fff;border:1px solid #e5e9f2;border-radius:14px;box-shadow:0 5px 18px rgba(19,35,67,.05)}.card{padding:18px}.card span{color:#667085;font-size:13px}.card b{display:block;font-size:25px;margin-top:8px}.panel{padding:18px}.panel-title{display:flex;align-items:center;justify-content:space-between;gap:14px}.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.input,.select{border:1px solid #d0d5dd;background:#fff;border-radius:9px;padding:10px 12px;color:#172033;min-width:0}.input:focus,.select:focus,textarea:focus{outline:3px solid #dbeafe;border-color:#84adff}.grow{flex:1}.primary,.secondary,.danger,.load-more{border:0;border-radius:9px;padding:10px 15px}.primary{background:#2563eb;color:#fff}.primary:hover{background:#1d4ed8}.secondary{background:#edf1f7;color:#344054}.secondary:hover{background:#e2e8f0}.danger{background:#fee4e2;color:#b42318}.danger:hover{background:#ffd6d2}.hidden{display:none!important}.query-toolbar{margin:18px 0 14px}.query-toolbar .input{width:280px}.query-toolbar .delimiter{width:90px}.query-toolbar .limit{width:100px}.tree-layout{display:grid;grid-template-columns:minmax(480px,1.1fr) minmax(360px,.9fr);gap:16px;align-items:start}.tree-panel,.preview-panel{min-height:520px}.tree-header{padding-bottom:13px;border-bottom:1px solid #edf0f5}.tree-root{padding-top:10px;min-height:410px;overflow:auto}.tree-node{position:relative}.tree-children{margin-left:22px;border-left:1px solid #dbe2ee;padding-left:10px}.tree-row{display:flex;align-items:center;gap:8px;min-height:39px;padding:5px 8px;border-radius:8px;user-select:none}.tree-row:hover{background:#f1f5fb}.tree-row.selected{background:#eaf2ff}.tree-toggle{width:22px;height:24px;border:0;background:transparent;color:#667085;padding:0;font-size:15px}.tree-icon{width:20px;text-align:center;color:#e69a24;font-size:15px}.leaf .tree-icon{color:#2563eb}.tree-name{font:13px Consolas,Monaco,monospace;color:#253858;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.tree-meta{font-size:11px;color:#98a2b3;white-space:nowrap}.tree-value{margin:2px 8px 9px 43px;background:#f8fafc;border:1px solid #e4e9f2;border-radius:9px;padding:10px}.tree-value-head{display:flex;justify-content:space-between;align-items:center;gap:10px;color:#667085;font-size:12px}.tree-value pre{margin:8px 0 0;max-height:160px;overflow:auto;white-space:pre-wrap;word-break:break-word;font:12px/1.5 Consolas,Monaco,monospace;color:#253858}.tree-loading,.empty{padding:30px 12px;text-align:center;color:#98a2b3;font-size:13px}.more-wrap{padding:8px 8px 8px 43px}.load-more{background:#f0f5ff;color:#175cd3;width:100%;text-align:left}.preview-panel{position:sticky;top:90px}.preview-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;padding-bottom:14px;border-bottom:1px solid #edf0f5}.preview-key{font:12px Consolas,Monaco,monospace;color:#175cd3;display:block;max-width:100%;overflow-wrap:anywhere;margin-top:5px}.preview-empty{display:grid;place-items:center;min-height:390px;color:#98a2b3;text-align:center;padding:30px}.preview-body{padding-top:14px}.value-tabs{display:flex;gap:6px;margin-bottom:10px}.value-tabs button{border:0;background:#edf1f7;color:#667085;border-radius:7px;padding:7px 11px;font-size:12px}.value-tabs button.active{background:#dbeafe;color:#175cd3}.value-editor{width:100%;min-height:320px;border:1px solid #d0d5dd;border-radius:9px;padding:12px;resize:vertical;font:13px/1.55 Consolas,Monaco,monospace;color:#172033;background:#fff}.value-formatted{width:100%;min-height:320px;max-height:500px;overflow:auto;margin:0;border:1px solid #d0d5dd;border-radius:9px;padding:12px;white-space:pre-wrap;word-break:break-word;font:13px/1.55 Consolas,Monaco,monospace;background:#f8fafc}.preview-actions{display:flex;gap:8px;margin-top:12px}.table-wrap{overflow:auto;margin-top:12px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 10px;border-bottom:1px solid #edf0f5;font-size:13px}th{color:#667085;font-weight:600}.sst{font:13px Consolas,Monaco,monospace;color:#344054}.badge{display:inline-block;border-radius:999px;background:#eef4ff;color:#175cd3;padding:3px 8px;font-size:11px}.toast{position:fixed;right:22px;bottom:22px;background:#172033;color:#fff;border-radius:9px;padding:12px 16px;box-shadow:0 8px 24px rgba(0,0,0,.18);display:none;z-index:20}.status-line{margin-top:7px}.about-list{margin:10px 0 0;padding-left:20px;color:#667085}@media(max-width:1050px){.tree-layout{grid-template-columns:1fr}.preview-panel{position:static}.cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){header{padding:0 15px}nav{width:62px;padding:14px 8px}nav button{justify-content:center;padding:11px 8px}nav button span:not(.nav-icon){display:none}.main{padding:18px 12px}.cards{grid-template-columns:1fr 1fr}.query-toolbar .input{width:100%}.query-toolbar .delimiter,.query-toolbar .limit{width:calc(50% - 5px)}.tree-panel,.preview-panel{padding:13px}}
</style>
</head>
<body>
<header><div class="brand"><div class="brand-mark">L</div><h1>LevelDB Viewer</h1></div><div class="top-query"><input class="input" id="quick" placeholder="Search key prefix..."><button class="primary" id="quickButton">Query</button></div><div class="connection"><i></i>Connected</div></header>
<div class="layout">
<nav><button data-page="dashboard" class="active"><span class="nav-icon">▦</span><span>Dashboard</span></button><button data-page="query"><span class="nav-icon">⌕</span><span>Key Tree</span></button><button data-page="sst"><span class="nav-icon">▤</span><span>SST Files</span></button><button data-page="about"><span class="nav-icon">?</span><span>About</span></button></nav>
<main class="main">
<section id="query" class="page"><h2>Key Tree</h2><div class="muted">Keys are grouped by delimiter and loaded only when a folder is expanded. Values are fetched only when a leaf is opened.</div><div class="toolbar query-toolbar"><input class="input" id="treePrefix" placeholder="Root prefix (optional)"><input class="input delimiter" id="treeDelimiter" value=":" maxlength="8" title="Key delimiter"><select class="select limit" id="treeLimit"><option value="100">100 nodes</option><option value="200" selected>200 nodes</option><option value="500">500 nodes</option><option value="1000">1000 nodes</option></select><button class="primary" id="scanTree">Build Tree</button><button class="secondary" id="expandVisible">Expand Visible</button></div><div class="tree-layout"><div class="panel tree-panel"><div class="panel-title tree-header"><div><h3>Key Explorer</h3><span id="treeSummary" class="muted">No tree loaded</span></div><button class="secondary" id="refreshTree">Refresh</button></div><div id="treeRoot" class="tree-root"><div class="empty">Build a tree to browse database keys.</div></div></div><div class="panel preview-panel"><div class="preview-head"><div><h3 id="previewTitle">Value Preview</h3><span id="previewKey" class="preview-key">Expand a leaf to inspect its value.</span></div><span id="previewSize" class="badge hidden"></span></div><div id="previewEmpty" class="preview-empty">Select a leaf node on the left.<br>Its value will be loaded on demand.</div><div id="previewBody" class="preview-body hidden"><div class="value-tabs"><button data-format="raw" class="active">Raw</button><button data-format="json">JSON</button><button data-format="hex">HEX</button><button data-format="base64">Base64</button></div><textarea id="previewEditor" class="value-editor"></textarea><pre id="previewFormatted" class="value-formatted hidden"></pre><div class="preview-actions"><button class="primary" id="saveRecord">Save</button><button class="danger" id="deleteRecord">Delete</button></div></div></div></div></section>
<section id="sst" class="page hidden"><h2>SST Files</h2><div class="muted">Files are listed from the opened database directory.</div><div class="panel table-wrap"><table><thead><tr><th>File</th><th>Level</th><th>Size</th><th>Compression</th></tr></thead><tbody id="sstRows"></tbody></table></div></section>
<section id="about" class="page hidden"><h2>About</h2><div class="panel"><p>LevelDB Viewer is a single executable browser console for inspecting hierarchical keys and editing records.</p><ul class="about-list"><li>Read operations do not require a password.</li><li>Put, Delete and Batch Write require the configured password.</li><li>Zstd-compressed LevelDB blocks are decoded by the embedded LevelDB build.</li></ul></div></section>
</main></div><div id="toast" class="toast"></div>
<script>
const state={tree:{prefix:'',delimiter:':',limit:200},cache:new Map(),selectedKey:'',selectedRecord:null};
const $=id=>document.getElementById(id);
const api=async(url,options)=>{const response=await fetch(url,options);let body;try{body=await response.json()}catch{throw Error('Server returned invalid JSON')}if(!response.ok)throw Error(body.error||response.statusText);return body};
const formatSize=bytes=>bytes<1024?bytes+' B':bytes<1048576?(bytes/1024).toFixed(1)+' KB':(bytes/1048576).toFixed(1)+' MB';
const showToast=message=>{const node=$('toast');node.textContent=message;node.style.display='block';setTimeout(()=>node.style.display='none',2400)};
const valueToHex=value=>Array.from(new TextEncoder().encode(value)).map(byte=>byte.toString(16).padStart(2,'0').toUpperCase()).join(' ');
const valueToBase64=value=>{const bytes=new TextEncoder().encode(value);let binary='';for(let index=0;index<bytes.length;index+=0x8000)binary+=String.fromCharCode(...bytes.subarray(index,index+0x8000));return btoa(binary)};
const valueToJson=value=>{try{return JSON.stringify(JSON.parse(value),null,2)}catch{return 'Invalid JSON'}};
function navigate(pageName){document.querySelectorAll('nav button').forEach(button=>button.classList.toggle('active',button.dataset.page===pageName));document.querySelectorAll('.page').forEach(page=>page.classList.toggle('hidden',page.id!==pageName));if(pageName==='sst')loadSst()}
function makeNode(item){const wrapper=document.createElement('div');wrapper.className='tree-node '+(item.leaf?'leaf':'branch');wrapper.dataset.key=item.key||'';wrapper.dataset.prefix=item.prefix||'';const row=document.createElement('div');row.className='tree-row';const toggle=document.createElement('button');toggle.className='tree-toggle';toggle.type='button';toggle.textContent='▸';const icon=document.createElement('span');icon.className='tree-icon';icon.textContent=item.leaf?'◆':'▰';const name=document.createElement('span');name.className='tree-name';name.textContent=item.name;const meta=document.createElement('span');meta.className='tree-meta';meta.textContent=item.leaf?formatSize(item.valueSize):'folder';row.append(toggle,icon,name,meta);const children=document.createElement('div');children.className='tree-children hidden';wrapper.append(row,children);row.addEventListener('click',()=>item.leaf?toggleLeaf(wrapper,item):toggleBranch(wrapper,item));return wrapper}
function appendMore(container,prefix,nextKey){const holder=document.createElement('div');holder.className='more-wrap tree-more';const button=document.createElement('button');button.className='load-more';button.type='button';button.textContent='Load more nodes';button.addEventListener('click',async event=>{event.stopPropagation();holder.remove();await loadTreeChildren(container,prefix,nextKey,true)});holder.append(button);container.append(holder)}
async function loadTreeChildren(container,prefix,start='',append=false){if(!append){container.innerHTML='<div class="tree-loading">Loading child nodes...</div>'}try{const params=new URLSearchParams({prefix,delimiter:state.tree.delimiter,limit:String(state.tree.limit)});if(start)params.set('start',start);const data=await api('/api/kv/tree?'+params.toString());if(!append)container.replaceChildren();data.items.forEach(item=>container.append(makeNode(item)));container.dataset.loaded='true';container.dataset.nextKey=data.nextKey||'';if(data.hasMore)appendMore(container,prefix,data.nextKey);if(!data.items.length&&!append)container.innerHTML='<div class="empty">No keys under this prefix.</div>'}catch(error){if(!append)container.innerHTML='';const errorNode=document.createElement('div');errorNode.className='empty';errorNode.textContent=error.message;container.append(errorNode);throw error}}
async function toggleBranch(wrapper,item){const children=wrapper.querySelector(':scope > .tree-children');const toggle=wrapper.querySelector(':scope > .tree-row .tree-toggle');const opening=children.classList.contains('hidden');children.classList.toggle('hidden',!opening);wrapper.classList.toggle('open',opening);toggle.textContent=opening?'▾':'▸';if(opening&&!children.dataset.loaded)await loadTreeChildren(children,item.prefix)}
function createInlineValue(record){const detail=document.createElement('div');detail.className='tree-value hidden';const head=document.createElement('div');head.className='tree-value-head';const label=document.createElement('span');label.textContent='Value · '+formatSize(record.valueSize);const action=document.createElement('button');action.className='secondary';action.type='button';action.textContent='Open in preview';action.addEventListener('click',event=>{event.stopPropagation();selectRecord(record)});head.append(label,action);const pre=document.createElement('pre');pre.textContent=record.value||'(empty value)';detail.append(head,pre);return detail}
async function toggleLeaf(wrapper,item){let detail=wrapper.querySelector(':scope > .tree-value');if(!detail){detail=createInlineValue({key:item.key,value:'Loading...',valueSize:item.valueSize});wrapper.append(detail)}const opening=detail.classList.contains('hidden');detail.classList.toggle('hidden',!opening);wrapper.querySelector(':scope > .tree-row .tree-toggle').textContent=opening?'▾':'▸';if(!opening)return;try{const record=await getRecord(item.key);detail.replaceWith(createInlineValue(record));detail=wrapper.querySelector(':scope > .tree-value');detail.classList.remove('hidden');wrapper.querySelector(':scope > .tree-row .tree-toggle').textContent='▾';selectRecord(record)}catch(error){detail.querySelector('pre').textContent=error.message}}
async function getRecord(key){if(state.cache.has(key))return state.cache.get(key);const data=await api('/api/kv/get?key='+encodeURIComponent(key));if(!data.found)throw Error('Key not found');const record={key:data.key,value:data.value||'',valueSize:data.valueSize||0};state.cache.set(key,record);return record}
function selectRecord(record){state.selectedKey=record.key;state.selectedRecord=record;$('previewTitle').textContent='Value Preview';$('previewKey').textContent=record.key;$('previewSize').textContent=formatSize(record.valueSize);$('previewSize').classList.remove('hidden');$('previewBody').classList.remove('hidden');$('previewEmpty').classList.add('hidden');$('previewEditor').value=record.value;document.querySelectorAll('.value-tabs button').forEach(button=>button.classList.toggle('active',button.dataset.format==='raw'));renderFormat('raw');document.querySelectorAll('.tree-row').forEach(row=>row.classList.toggle('selected',row.parentElement.dataset.key===record.key))}
function renderFormat(format){const raw=$('previewEditor');const formatted=$('previewFormatted');document.querySelectorAll('.value-tabs button').forEach(button=>button.classList.toggle('active',button.dataset.format===format));if(format==='raw'){raw.classList.remove('hidden');formatted.classList.add('hidden');return}raw.classList.add('hidden');formatted.classList.remove('hidden');const value=state.selectedRecord?state.selectedRecord.value:'';formatted.textContent=format==='json'?valueToJson(value):format==='hex'?valueToHex(value):valueToBase64(value)}
async function scanTree(){state.tree={prefix:$('treePrefix').value,delimiter:$('treeDelimiter').value||':',limit:Number($('treeLimit').value)||200};state.cache.clear();$('treeRoot').innerHTML='<div class="tree-loading">Loading top-level nodes...</div>';try{const params=new URLSearchParams({prefix:state.tree.prefix,delimiter:state.tree.delimiter,limit:String(state.tree.limit)});const data=await api('/api/kv/tree?'+params.toString());$('treeRoot').replaceChildren();data.items.forEach(item=>$('treeRoot').append(makeNode(item)));if(data.hasMore)appendMore($('treeRoot'),state.tree.prefix,data.nextKey);if(!data.items.length)$('treeRoot').innerHTML='<div class="empty">No keys matched this prefix.</div>';$('treeSummary').textContent=data.count+' top-level nodes'+(data.hasMore?' · more available':'')}catch(error){$('treeRoot').innerHTML='<div class="empty"></div>';$('treeRoot').firstChild.textContent=error.message;showToast(error.message)}}
async function expandVisible(){const branches=[...document.querySelectorAll('#treeRoot > .tree-node.branch')];for(const branch of branches){if(branch.classList.contains('open'))continue;const item={prefix:branch.dataset.prefix};await toggleBranch(branch,item)}}
async function saveRecord(){if(!state.selectedKey)return;const password=prompt('Password for write operation:');if(password===null)return;const value=$('previewEditor').value;try{await api('/api/kv/put?pwd='+encodeURIComponent(password),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:state.selectedKey,value})});const record={key:state.selectedKey,value,valueSize:new TextEncoder().encode(value).length};state.cache.set(state.selectedKey,record);state.selectedRecord=record;selectRecord(record);showToast('Saved');await scanTree()}catch(error){showToast(error.message)}}
async function deleteRecord(){if(!state.selectedKey||!confirm('Delete '+state.selectedKey+'?'))return;const password=prompt('Password for write operation:');if(password===null)return;try{await api('/api/kv/delete?pwd='+encodeURIComponent(password),{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({key:state.selectedKey})});showToast('Deleted');state.cache.delete(state.selectedKey);state.selectedKey='';state.selectedRecord=null;$('previewBody').classList.add('hidden');$('previewEmpty').classList.remove('hidden');await scanTree()}catch(error){showToast(error.message)}}
async function loadSst(){try{const data=await api('/api/sst/list');$('sstRows').replaceChildren();data.items.forEach(file=>{const row=document.createElement('tr');[file.name,'L'+file.level,formatSize(file.size),file.compression].forEach((value,index)=>{const cell=document.createElement('td');cell.textContent=value;if(index===0)cell.className='sst';if(index===3){cell.innerHTML='';const badge=document.createElement('span');badge.className='badge';badge.textContent=value;cell.append(badge)}row.append(cell)});$('sstRows').append(row)})}catch(error){showToast(error.message)}}
document.querySelectorAll('nav button').forEach(button=>button.addEventListener('click',()=>navigate(button.dataset.page)));$('scanTree').addEventListener('click',scanTree);$('refreshTree').addEventListener('click',scanTree);$('expandVisible').addEventListener('click',()=>expandVisible().catch(error=>showToast(error.message)));$('quickButton').addEventListener('click',()=>{navigate('query');$('treePrefix').value=$('quick').value;scanTree()});$('quick').addEventListener('keydown',event=>{if(event.key==='Enter')$('quickButton').click()});document.querySelectorAll('.value-tabs button').forEach(button=>button.addEventListener('click',()=>renderFormat(button.dataset.format)));$('saveRecord').addEventListener('click',saveRecord);$('deleteRecord').addEventListener('click',deleteRecord);scanTree();
</script>
</body>
</html>)HTML";
}